import numpy as np
from scipy.optimize import minimize

N = 38

# EVOLVE-BLOCK-START
def construct():
    """
    Construct the global minimum configuration for LJ38.
    The global minimum is a truncated octahedron from the FCC lattice.
    """
    
    # 1. Generate FCC lattice points
    # FCC lattice vectors can be generated by taking all integer triples (i, j, k)
    # where i + j + k is even, and scaling by 1/sqrt(2).
    # However, it's easier to think of FCC as a simple cubic lattice with a basis,
    # or just generate a large cubic box of integer coords and filter.
    
    # Let's generate a range of integer coordinates.
    # The cluster has 38 atoms. A truncated octahedron in FCC has shells.
    # Shell 0: 1 atom (0,0,0)
    # Shell 1: 12 atoms (nearest neighbors)
    # Shell 2: 6 atoms (next nearest, face centers) + 6 (edge centers? no, FCC structure)
    # Let's just generate a large enough box and pick the closest 38.
    
    # Range of indices to cover the cluster
    range_lim = 5
    points = []
    for i in range(-range_lim, range_lim + 1):
        for j in range(-range_lim, range_lim + 1):
            for k in range(-range_lim, range_lim + 1):
                # FCC condition: i+j+k is even
                if (i + j + k) % 2 == 0:
                    points.append((i, j, k))
    
    points = np.array(points, dtype=float)
    
    # Calculate squared distances from origin to sort
    distances_sq = np.sum(points**2, axis=1)
    
    # Sort by distance
    sorted_indices = np.argsort(distances_sq)
    
    # Take the 38 closest points
    # Note: There might be ties in distance. The standard LJ38 global minimum
    # corresponds to the first 38 points in the FCC lattice centered at the origin.
    # The shells are:
    # 1 atom at d=0
    # 12 atoms at d=sqrt(2) (in integer coords, scaled later)
    # 6 atoms at d=sqrt(4)=2
    # 24 atoms at d=sqrt(6)
    # Total so far: 1 + 12 + 6 + 24 = 43.
    # Wait, let's verify the shell structure of FCC.
    # (0,0,0) -> 1
    # (1,1,0) permutations -> 12 (dist sq = 2)
    # (2,0,0) permutations -> 6 (dist sq = 4)
    # (2,1,1) permutations -> 24 (dist sq = 6)
    # (3,1,0) permutations -> 24 (dist sq = 10)
    # The 38th atom falls into the shell with dist sq = 6.
    # 1 + 12 + 6 = 19. We need 38-19=19 more from the 24 available in the next shell.
    # Due to symmetry, any 19 from the 24 will yield the same energy?
    # Actually, the "truncated octahedron" usually implies a specific subset.
    # However, because of the high symmetry, selecting the closest 38 is the standard way to define this cluster.
    # The 24 points at dist sq=6 are equivalent by symmetry. Selecting any 19 of them
    # might break symmetry, but the energy landscape is flat with respect to which 19 are chosen
    # if we allow relaxation. However, the true global minimum is a specific symmetric structure.
    # Let's check if the 38th shell is fully populated or partial.
    # If it's partial, the structure is not perfectly symmetric.
    # Literature states LJ38 global min is a "truncated octahedron".
    # A regular truncated octahedron has 48 vertices. 
    # Wait, the FCC cluster with 38 atoms is often described as a truncated octahedron.
    # Let's re-evaluate the count.
    # Maybe the scaling is different.
    
    # Let's just take the 38 closest. If there are ties, the order from numpy might be arbitrary.
    # To be safe and deterministic, we should handle ties carefully or rely on the relaxation.
    # However, the 24 points at dist^2=6 are all equivalent.
    # If we pick 19 of them, we have a specific structure.
    # Actually, the global minimum of LJ38 is known to be a structure that can be derived from FCC.
    # Let's proceed with the 38 closest.
    
    cluster_points = points[sorted_indices[:N]]
    
    # Center the cluster
    center = np.mean(cluster_points, axis=0)
    cluster_points = cluster_points - center
    
    # 2. Scaling
    # The integer coordinates are in units of the FCC lattice parameter 'a'.
    # The nearest neighbor distance in integer coords is sqrt(2).
    # We want the nearest neighbor distance in real space to be r_min = 2^(1/6).
    # So, scale factor s such that s * sqrt(2) = 2^(1/6)
    # s = 2^(1/6) / sqrt(2) = 2^(1/6 - 3/6) = 2^(-2/6) = 2^(-1/3)
    
    scale = 2.0 ** (-1.0 / 3.0)
    cluster_points = cluster_points * scale
    
    # 3. Optimization
    # Define the energy function
    def energy(pos):
        # pos is shape (N, 3)
        # Calculate all pairwise distances
        # diff[i,j] = pos[i] - pos[j]
        diff = pos[:, np.newaxis, :] - pos[np.newaxis, :, :]
        dist_sq = np.sum(diff**2, axis=2)
        # Avoid division by zero for i==j
        np.fill_diagonal(dist_sq, 1.0)
        dist = np.sqrt(dist_sq)
        
        # LJ potential: 4 * (r^-12 - r^-6)
        # We only need to sum over i < j
        # Using upper triangle
        iu = np.triu_indices(N, k=1)
        r = dist[iu]
        r6 = r**-6
        r12 = r6 * r6
        return 4.0 * np.sum(r12 - r6)
    
    # Use L-BFGS-B for local relaxation
    # This ensures we are at the exact minimum of this topology
    res = minimize(
        energy, 
        cluster_points.flatten(), 
        method='L-BFGS-B', 
        options={'maxiter': 1000, 'ftol': 1e-12, 'gtol': 1e-12}
    )
    
    # Reshape back to (N, 3)
    optimized_pos = res.x.reshape(N, 3)
    
    return optimized_pos
# EVOLVE-BLOCK-END
